import React, { useState } from "react";

function ApplyForm() {
  const [formData, setFormData] = useState({
    name: "",
    truckName: "",
    city: "",
    cuisine: "",
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Form Submitted", formData);
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 p-6">
      <form
        onSubmit={handleSubmit}
        className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md"
      >
        <h2 className="text-2xl font-bold text-center mb-6 text-purple-600">
          🚚 Vendor Application Form
        </h2>

        {["name", "truckName", "city", "cuisine"].map((field) => (
          <div key={field} className="mb-4">
            <label className="block text-gray-700 mb-2 capitalize">
              {field}
            </label>
            <input
              type="text"
              name={field}
              value={formData[field]}
              onChange={handleChange}
              className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-purple-400 outline-none"
              placeholder={`Enter ${field}`}
              required
            />
          </div>
        ))}

        <button
          type="submit"
          className="w-full bg-purple-600 text-white font-semibold py-3 rounded-lg hover:bg-purple-700 transition"
        >
          Submit Application
        </button>
      </form>
    </div>
  );
}

export default ApplyForm;
